@Test
public void testMultiValueIndexing() throws Exception {
    final FieldSpec mvIntFs = new DimensionFieldSpec(COL_NAME, FieldSpec.DataType.LONG, false);
    final LongMutableDictionary dict = new LongMutableDictionary(mvIntFs);
    final FixedByteSingleColumnMultiValueReaderWriter indexer = new FixedByteSingleColumnMultiValueReaderWriter(NROWS, Integer.SIZE / 8, MAX_N_VALUES);
    // Insert rows into the indexer and dictionary
    Random random = new Random(RANDOM_SEED);
    for (int row = 0; row < NROWS; row++) {
        int nValues = Math.abs(random.nextInt()) % MAX_N_VALUES;
        Long[] val = new Long[nValues];
        for (int i = 0; i < nValues; i++) {
            val[i] = random.nextLong();
        }
        dict.index(val);
        int[] dictIds = new int[nValues];
        for (int i = 0; i < nValues; i++) {
            dictIds[i] = dict.indexOf(val[i]);
        }
        indexer.setIntArray(row, dictIds);
    }
    // Read back rows and make sure that the values are good.
    random = new Random(RANDOM_SEED);
    final int[] dictIds = new int[MAX_N_VALUES];
    for (int row = 0; row < NROWS; row++) {
        int nValues = indexer.getIntArray(row, dictIds);
        Assert.assertEquals(nValues, Math.abs(random.nextInt()) % MAX_N_VALUES, "Mismatching number of values, random seed is: " + RANDOM_SEED);
        for (int i = 0; i < nValues; i++) {
            Long val = dict.getLongValue(dictIds[i]);
            Assert.assertEquals(val.longValue(), random.nextLong(), "Value mismatch at row " + row + ", random seed is: " + RANDOM_SEED);
        }
    }
}

@Test
public void testDropInvalidRows() throws Exception {
    Schema schema = new Schema.SchemaBuilder().setSchemaName("potato").addSingleValueDimension("dimension", FieldSpec.DataType.STRING).addMetric("metric", FieldSpec.DataType.LONG).addTime("time", TimeUnit.SECONDS, FieldSpec.DataType.LONG).build();
    RealtimeSegmentImpl realtimeSegment = new RealtimeSegmentImpl(schema, 100, "noTable", "noSegment", schema.getSchemaName(), new ServerMetrics(new MetricsRegistry()));
    // Segment should be empty
    Assert.assertEquals(realtimeSegment.getRawDocumentCount(), 0);
    Map<String, Object> genericRowContents = new HashMap<>();
    genericRowContents.put("dimension", "potato");
    genericRowContents.put("metric", 1234L);
    genericRowContents.put("time", 4567L);
    GenericRow row = new GenericRow();
    row.init(genericRowContents);
    // Add a valid row
    boolean notFull = realtimeSegment.index(row);
    Assert.assertEquals(notFull, true);
    Assert.assertEquals(realtimeSegment.getRawDocumentCount(), 1);
    // Add an invalid row
    genericRowContents.put("metric", null);
    notFull = realtimeSegment.index(row);
    Assert.assertEquals(notFull, true);
    Assert.assertEquals(realtimeSegment.getRawDocumentCount(), 1);
