        String d2 = (String) datum.get("d2");
        String d2_raw = (String) datum.get("d2_raw");
        Assert.assertEquals("Incorrect topk column transformation", (d2_raw.equals("pqr1") && d2.equals("other")) || (d2_raw.equals("pqr2") && d2.equals("pqr2")), true);
    }
}

